import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 3
    records = list(
        csv.reader(
            io.StringIO(raw_csv.removeprefix("\ufeff"), newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
        )
    )
    if not records:
        return {"columns": [], "rows": []}

    header_index = next(
        (
            index
            for index, record in enumerate(records)
            if len(record) == expected_width
            and all(field.strip() for field in record)
        ),
        None,
    )
    if header_index is None:
        header_index = next(
            (
                index
                for index, record in enumerate(records)
                if any(field.strip() for field in record)
            ),
            None,
        )
    if header_index is None:
        return {
            "columns": [f"column_{index}" for index in range(1, expected_width + 1)],
            "rows": [
                record + [""] * (expected_width - len(record))
                for record in records
            ],
        }

    columns = records[header_index][:]
    data = records[header_index + 1 :]
    width = max(expected_width, len(columns), max(map(len, data), default=0))
    used_names = set(columns)
    while len(columns) < width:
        base = f"column_{len(columns) + 1}"
        name = base
        suffix = 2
        while name in used_names:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used_names.add(name)

    return {
        "columns": columns,
        "rows": [record + [""] * (width - len(record)) for record in data],
    }
